<div class="webappick-row">
    <div class="webappick-col-12">
        <!-- Header -->
        <div class="webappick-header webappick-mt-md-5">
            <div class="webappick-header-body">

                <!-- Title -->
                <h1 class="webappick-header-title">
                    Button group
                </h1>

                <!-- Subtitle -->
                <p class="webappick-header-subtitle">
                    Group a series of buttons together on a single line with the button group, and super-power them with JavaScript. Please read the <a target="_blank" href="https://getbootstrap.com/docs/4.0/components/button-group/">official Bootstrap documentation</a> for a full list of options.
                </p>

            </div>
        </div>

        <!-- Card -->
        <div class="webappick-card">
            <div class="webappick-card-body">

                <!-- Button toolbar -->
                <div class="webappick-btn-toolbar" role="toolbar" aria-label="Toolbar with button groups">

