                    <div class="webappick-btn-group webappick-mr-2 webappick-mb-3" role="group" aria-label="First group">
                        <button type="button" class="webappick-btn webappick-btn-secondary">1</button>
                        <button type="button" class="webappick-btn webappick-btn-secondary">2</button>
                        <button type="button" class="webappick-btn webappick-btn-secondary">3</button>
                        <button type="button" class="webappick-btn webappick-btn-secondary">4</button>
                    </div>

                    <!-- Button group -->
                    <div class="webappick-btn-group webappick-mr-2 webappick-mb-3" role="group" aria-label="Second group">
                        <button type="button" class="webappick-btn webappick-btn-secondary">5</button>
                        <button type="button" class="webappick-btn webappick-btn-secondary">6</button>
                        <button type="button" class="webappick-btn webappick-btn-secondary">7</button>
                    </div>

                    <!-- Button group -->
                    <div class="webappick-btn-group webappick-mr-2 webappick-mb-3" role="group" aria-label="Third group">
                        <button type="button" class="webappick-btn webappick-btn-secondary">8</button>
                    </div>

                    <!-- Button group -->
                    <div class="webappick-btn-group webappick-mb-3" role="group" aria-label="Button group with nested dropdown">
                        <button type="button" class="webappick-btn webappick-btn-secondary">1</button>
                        <button type="button" class="webappick-btn webappick-btn-secondary">2</button>

                        <!-- Button group -->
                        <div class="webappick-btn-group" role="group">
                            <button id="btnGroupDrop1" type="button" class="webappick-btn webappick-btn-secondary webappick-dropdown-toggle" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">
                                Dropdown
                            </button>
                            <div class="webappick-dropdown-menu" aria-labelledby="btnGroupDrop1" style="">
                                <a class="webappick-dropdown-item" href="#">Dropdown link</a>
                                <a class="webappick-dropdown-item" href="#">Dropdown link</a>
                            </div>
                        </div>
                    </div>

                </div>

                <!-- Button group -->
                <div class="webappick-btn-group webappick-btn-group-lg webappick-mr-2 webappick-mb-3" role="group" aria-label="First group">
                    <button type="button" class="webappick-btn webappick-btn-warning">1</button>
                    <button type="button" class="webappick-btn webappick-btn-warning">2</button>
                    <button type="button" class="webappick-btn webappick-btn-warning">3</button>
                    <button type="button" class="webappick-btn webappick-btn-warning">4</button>
                </div>

                <!-- Button group -->
                <div class="webappick-btn-group webappick-btn-group webappick-mr-2 webappick-mb-3" role="group" aria-label="First group">
                    <button type="button" class="webappick-btn webappick-btn-success">1</button>
                    <button type="button" class="webappick-btn webappick-btn-success">2</button>
                    <button type="button" class="webappick-btn webappick-btn-success">3</button>
                    <button type="button" class="webappick-btn webappick-btn-success">4</button>
                </div>

                <!-- Button group -->
                <div class="webappick-btn-group webappick-btn-group-sm webappick-mr-2 webappick-mb-3" role="group" aria-label="First group">
                    <button type="button" class="webappick-btn webappick-btn-primary">1</button>
                    <button type="button" class="webappick-btn webappick-btn-primary">2</button>
                    <button type="button" class="webappick-btn webappick-btn-primary">3</button>
                    <button type="button" class="webappick-btn webappick-btn-primary">4</button>
                </div>

            </div>
